#!/usr/bin/env bash

set -euo pipefail

# Register a JSON schema in the Schema Registry.
#
# The Schema Registry REST API is served over HTTPS (securehttp: true) with a
# certificate generated by ssr-operator and signed by the Kafka cluster CA.
# Its SANs cover the service DNS name only:
#
#   confluent-schema-registry
#   confluent-schema-registry.kafka
#   confluent-schema-registry.kafka.svc
#   confluent-schema-registry.kafka.svc.cluster
#   confluent-schema-registry.kafka.svc.cluster.local
#
# The ingress hostname (schema.kind.cluster) is NOT part of that certificate,
# so hostname verification would fail against it. Instead the request is sent
# through a port-forward to the service, using the service DNS name for both
# name resolution and TLS verification.

readonly NAMESPACE=kafka
readonly REGISTRY=confluent-schema-registry
readonly REGISTRY_HOST="${REGISTRY}.${NAMESPACE}.svc"
readonly LOCAL_PORT=8443
readonly SUBJECT=example-topic
readonly CLUSTER_CA_SECRET=kafka-cluster-cluster-ca-cert

WORKDIR=$(mktemp -d)
CA_FILE="${WORKDIR}/ca.crt"
PORT_FORWARD_PID=""

cleanup(){
  if [ -n "$PORT_FORWARD_PID" ]; then
    kill "$PORT_FORWARD_PID" 2>/dev/null || true
    wait "$PORT_FORWARD_PID" 2>/dev/null || true
  fi
  rm -rf "$WORKDIR"
}
trap cleanup EXIT

echo ">>> Extracting the Kafka cluster CA certificate"
kubectl get secret "$CLUSTER_CA_SECRET" --namespace "$NAMESPACE" \
  --output jsonpath='{.data.ca\.crt}' | base64 --decode > "$CA_FILE"

echo ">>> Port-forwarding ${REGISTRY} service to localhost:${LOCAL_PORT}"
kubectl port-forward --namespace "$NAMESPACE" "service/${REGISTRY}" \
  "${LOCAL_PORT}:443" >/dev/null 2>&1 &
PORT_FORWARD_PID=$!

# Wait for the port-forward to accept connections
for _ in $(seq 1 30); do
  if curl --silent --output /dev/null --cacert "$CA_FILE" \
      --resolve "${REGISTRY_HOST}:${LOCAL_PORT}:127.0.0.1" \
      "https://${REGISTRY_HOST}:${LOCAL_PORT}/subjects"; then
    break
  fi
  sleep 1
done

echo ">>> Registering JSON schema for subject ${SUBJECT}"
echo '{
  "type": "object",
  "properties": {
    "user": {
      "type": "string"
    },
    "car": {
      "type": "string"
    },
    "color": {
      "type": "string"
    }
  }
}' | jq '. | {schema: tojson, schemaType: "JSON"}' | \
curl --fail-with-body --silent --show-error \
  --request POST \
  --cacert "$CA_FILE" \
  --resolve "${REGISTRY_HOST}:${LOCAL_PORT}:127.0.0.1" \
  --header "Content-Type: application/vnd.schemaregistry.v1+json" \
  --data @- \
  "https://${REGISTRY_HOST}:${LOCAL_PORT}/subjects/${SUBJECT}/versions"
echo
